import{_ as o,o as n,c as s,a2 as r}from"./chunks/framework.CBVBgcDP.js";const h=JSON.parse('{"title":"多模态：一张图怎么变成 token","description":"","frontmatter":{"title":"多模态：一张图怎么变成 token","tags":["LLM","多模态","ViT","CLIP","SigLIP","视觉编码器","M-RoPE"],"date":"2026-08-16"},"headers":[],"relativePath":"ai/llm-basics/multimodal.md","filePath":"ai/llm-basics/multimodal.md","lastUpdated":1786875695000}'),a={name:"ai/llm-basics/multimodal.md"};function e(l,t,i,g,d,p){return n(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="多模态-一张图怎么变成-token" tabindex="-1">多模态：一张图怎么变成 token <a class="header-anchor" href="#多模态-一张图怎么变成-token" aria-label="Permalink to &quot;多模态：一张图怎么变成 token&quot;">​</a></h1><blockquote><p><strong>这篇文档只回答一个问题：一张图片，怎么变成能进 <a href="/blog/ai/llm-basics/glossary.html#_0-骨架">Transformer 那 12 行</a> 的东西。</strong></p><p>一旦它变成了 token，后面的事——残差流、attention、FFN、KV Cache、采样——<strong>一个字都不用改</strong>。模型不知道自己在看图。这是全文最重要的一句话。</p><p>每个条目固定三行：<strong>是什么</strong> / <strong>一个可验证的数字</strong> / <strong>没有它会坏在哪</strong>。</p><p>🔗 前置：<a href="/blog/ai/llm-basics/glossary.html">LLM 基础：跟着一个 token 走完全程</a></p></blockquote><hr><h2 id="_0-骨架" tabindex="-1">0. 骨架 <a class="header-anchor" href="#_0-骨架" aria-label="Permalink to &quot;0. 骨架&quot;">​</a></h2><p><a href="/blog/ai/llm-basics/glossary.html#_0-骨架">glossary §0</a> 的第一行是 <code>ids = tokenizer.encode(text)</code>。多模态做的全部事情，就是给这一行加一条平行支路：</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 文本支路（glossary §1，原样不动）</span></span>
<span class="line"><span style="color:#BABED8;">text_emb </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> embedding</span><span style="color:#89DDFF;">[</span><span style="color:#BABED8;">tokenizer</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">encode</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">这张图里有几只猫？</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)]</span><span style="color:#676E95;font-style:italic;">   # → [T_txt, d_model]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 图像支路（本文全部内容）</span></span>
<span class="line"><span style="color:#BABED8;">patches  </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> split</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">image</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> patch_size</span><span style="color:#89DDFF;">=</span><span style="color:#F78C6C;">14</span><span style="color:#89DDFF;">)</span><span style="color:#676E95;font-style:italic;">        # → [N, 14, 14, 3]   §1</span></span>
<span class="line"><span style="color:#BABED8;">feats    </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> vision_encoder</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">patches</span><span style="color:#89DDFF;">)</span><span style="color:#676E95;font-style:italic;">            # → [N, d_vis]        §2</span></span>
<span class="line"><span style="color:#BABED8;">img_emb  </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> projector</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">feats</span><span style="color:#89DDFF;">)</span><span style="color:#676E95;font-style:italic;">                   # → [N, d_model]      §3  ★对齐到同一维度</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 汇流——从这里开始，两者再无区别</span></span>
<span class="line"><span style="color:#BABED8;">x </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> concat</span><span style="color:#89DDFF;">([</span><span style="color:#82AAFF;">img_emb</span><span style="color:#89DDFF;">,</span><span style="color:#82AAFF;"> text_emb</span><span style="color:#89DDFF;">])</span><span style="color:#676E95;font-style:italic;">               # → [N + T_txt, d_model]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">for</span><span style="color:#BABED8;"> layer </span><span style="color:#89DDFF;font-style:italic;">in</span><span style="color:#82AAFF;"> range</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">L</span><span style="color:#89DDFF;">):</span><span style="color:#676E95;font-style:italic;">                        # ← glossary §2~§4，一字未改</span></span>
<span class="line"><span style="color:#BABED8;">    x </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> x </span><span style="color:#89DDFF;">+</span><span style="color:#82AAFF;"> attn</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">rmsnorm</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">x</span><span style="color:#89DDFF;">))</span></span>
<span class="line"><span style="color:#BABED8;">    x </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> x </span><span style="color:#89DDFF;">+</span><span style="color:#82AAFF;"> ffn </span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">rmsnorm</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">x</span><span style="color:#89DDFF;">))</span></span>
<span class="line"><span style="color:#BABED8;">...                                           </span><span style="color:#676E95;font-style:italic;"># ← glossary §5~§6，一字未改</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>三件事看完这段就该记住：</p><ol><li><strong><code>projector</code> 那一行是全部的魔法</strong>。它把视觉编码器的输出维度 <code>d_vis</code> 掰成 <code>d_model</code>，让图像向量能挤进<a href="/blog/ai/llm-basics/glossary.html#残差流-residual-stream">残差流</a>。掰完之后，它在数值上和一个词的 embedding 没有任何区别。</li><li><strong>图像 token 是真 token</strong>。它占上下文、占 <a href="/blog/ai/llm-basics/glossary.html#kv-cache">KV Cache</a>、按 <code>O(T²)</code> 参与 attention、要花钱。「传图便宜」是错觉。</li><li><strong><code>N</code> 是这篇文章的主角</strong>。一张图变成多少个 token，是所有多模态成本、所有分辨率取舍、所有失败模式的唯一自变量。</li></ol><h3 id="速查表" tabindex="-1">速查表 <a class="header-anchor" href="#速查表" aria-label="Permalink to &quot;速查表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名词</th><th>在哪</th><th>名词</th><th>在哪</th></tr></thead><tbody><tr><td>Patch / patch_size</td><td><a href="#_1-切块-patch-就是图像的-token">§1</a></td><td>像素重排 / 2×2 合并</td><td><a href="#_3-连接器-怎么接进残差流">§3</a></td></tr><tr><td>ViT / CLIP / SigLIP</td><td><a href="#_2-视觉编码器-把-patch-变成向量">§2</a></td><td>图像计费公式</td><td><a href="#_4-账单-一张图到底多少-token">§4</a></td></tr><tr><td>DINOv2 / v3</td><td><a href="#_2-视觉编码器-把-patch-变成向量">§2</a></td><td>M-RoPE / RoPE-2D</td><td><a href="#_5-位置编码-二维的顺序">§5</a></td></tr><tr><td>线性投影 / MLP 连接器</td><td><a href="#_3-连接器-怎么接进残差流">§3</a></td><td>视频 / 音频 token 率</td><td><a href="#_6-视频与音频-把时间也切成-token">§6</a></td></tr><tr><td>Q-Former / Perceiver</td><td><a href="#_3-连接器-怎么接进残差流">§3</a></td><td>早期融合 / 原生多模态</td><td><a href="#_7-原生多模态-原生在哪">§7</a></td></tr><tr><td>交叉注意力适配器</td><td><a href="#_3-连接器-怎么接进残差流">§3</a></td><td>分辨率悬崖</td><td><a href="#_8-坏在哪里">§8</a></td></tr></tbody></table><hr><h2 id="_1-切块-patch-就是图像的-token" tabindex="-1">1. 切块：patch 就是图像的 token <a class="header-anchor" href="#_1-切块-patch-就是图像的-token" aria-label="Permalink to &quot;1. 切块：patch 就是图像的 token&quot;">​</a></h2><h3 id="patch-图块" tabindex="-1">Patch（图块） <a class="header-anchor" href="#patch-图块" aria-label="Permalink to &quot;Patch（图块）&quot;">​</a></h3><ul><li><p><strong>是什么</strong>：把图像切成不重叠的 <code>P×P</code> 小方块，每块拉平成一个向量，当成一个 token。<strong>这就是图像世界的<a href="/blog/ai/llm-basics/glossary.html#token-分词-tokenization">分词</a></strong>——只不过它不需要学，是纯粹的几何切割。</p></li><li><p><strong>数字</strong>：token 数 <code>N = (H/P) × (W/P)</code>。<code>P</code> 只有三个常见值：<strong>14、16、32</strong>。</p><table tabindex="0"><thead><tr><th>编码器</th><th>分辨率</th><th>patch</th><th><strong>token 数</strong></th></tr></thead><tbody><tr><td>ViT-B/16</td><td>224</td><td>16</td><td>196（+1 CLS = 197）</td></tr><tr><td>CLIP ViT-L/14</td><td>224</td><td>14</td><td><strong>256</strong></td></tr><tr><td>CLIP ViT-L/14@336</td><td>336</td><td>14</td><td><strong>576</strong></td></tr><tr><td>SigLIP So400m/14</td><td>384</td><td>14</td><td>729</td></tr><tr><td>DINOv3 ViT-7B/16</td><td>224</td><td>16</td><td>196（+1 CLS +4 register = 201）</td></tr></tbody></table></li><li><p><strong>没有它会坏在哪</strong>：不切块就得让每个像素当一个 token。224×224 = <strong>50,176 个 token</strong>，而 attention 是 <code>O(T²)</code>——一张最小尺寸的图就能把 attention 撑爆。<strong>切块首先是一个压缩手段</strong>，和<a href="/blog/ai/llm-basics/glossary.html#token-分词-tokenization">子词分词</a>的动机一模一样。</p></li><li><p><strong>⚠️ 二次方陷阱</strong>：<code>N</code> 随边长<strong>平方</strong>增长，不是线性。分辨率从 224 提到 336，token 从 256 涨到 576（2.25×）；提到 896，涨到 4096（16×）。<strong>「把分辨率调高一点」在成本上从来不是「一点」。</strong></p></li></ul><h3 id="为什么是-14-和-16" tabindex="-1">为什么是 14 和 16 <a class="header-anchor" href="#为什么是-14-和-16" aria-label="Permalink to &quot;为什么是 14 和 16&quot;">​</a></h3><ul><li>这两个数不是调出来的，是<strong>算力预算的直接后果</strong>。224/14 = 16，224/16 = 14，都落在「几百个 token」这个和文本序列可比的量级上。</li><li>DINOv3（2025）把 patch 从 14 <strong>改回了 16</strong>，224px 下 token 从 261 降到 201。这是一次明确的成本让步——在特征质量和序列长度之间，它选了后者。</li></ul><hr><h2 id="_2-视觉编码器-把-patch-变成向量" tabindex="-1">2. 视觉编码器：把 patch 变成向量 <a class="header-anchor" href="#_2-视觉编码器-把-patch-变成向量" aria-label="Permalink to &quot;2. 视觉编码器：把 patch 变成向量&quot;">​</a></h2><h3 id="vit-vision-transformer" tabindex="-1">ViT（Vision Transformer） <a class="header-anchor" href="#vit-vision-transformer" aria-label="Permalink to &quot;ViT（Vision Transformer）&quot;">​</a></h3><ul><li><strong>是什么</strong>：patch 拉平 → 线性投影 → 加位置编码 → 走 <code>L</code> 层标准 Transformer block。<strong>注意：和 <a href="/blog/ai/llm-basics/glossary.html#_2-主干-残差流">glossary §2~§4</a> 描述的结构完全相同</strong>，唯一区别是它<strong>不用因果掩码</strong>——图像没有「未来」，每个 patch 能看见所有 patch（双向）。</li><li><strong>数字</strong>：ViT-B / L / H 的隐藏维度是 <strong>768 / 1024 / 1280</strong>。CLIP ViT-L/14 是 24 层、宽 1024、16 头，<strong>约 304M 参数</strong>。</li><li><strong>没有它会坏在哪</strong>：直接把原始像素块投影进 LLM，你得到的是一堆没有语义的颜色统计。编码器的作用是<strong>把像素变成语义</strong>——「这块是猫耳朵」而不是「这块偏棕色」。</li></ul><h3 id="clip-siglip-语义从哪来" tabindex="-1">CLIP / SigLIP：语义从哪来 <a class="header-anchor" href="#clip-siglip-语义从哪来" aria-label="Permalink to &quot;CLIP / SigLIP：语义从哪来&quot;">​</a></h3><ul><li><strong>是什么</strong>：视觉编码器的语义不是凭空来的，是<strong>用图文对训出来的</strong>。CLIP 用对比学习（一个 batch 内做 softmax 匹配），SigLIP 换成 <strong>sigmoid 逐对损失</strong>，去掉了 batch 内归一化。</li><li><strong>数字</strong>：CLIP 训练用了 <strong>4 亿图文对</strong>。SigLIP 的效率提升很直白：SigLiT 在 <strong>4 块 TPUv4 上训 2 天就到 84.5% ImageNet 零样本</strong>。SigLIP 2 的规格档位：Base 86M / Large 303M / <strong>So400m 400M</strong> / giant 1B，输出维度 <strong>1152</strong>（So400m-patch14-384）。</li><li><strong>没有它会坏在哪</strong>：<strong>它决定了 LLM「能看见什么」的上限。</strong> 编码器没学过的概念，后面再大的 LLM 也读不出来——投影层不会凭空造出信息。这是多模态最常被忽略的瓶颈：大家盯着 LLM 的参数量，但天花板往往在那个 400M 的编码器上。</li><li><strong>⚠️ 现在的默认选择是 SigLIP 不是 CLIP</strong>。Gemma 3 用 SigLIP 400M，且<strong>三个尺寸（4B/12B/27B）共用同一个编码器并全程冻结</strong>。编码器已经变成了一个可复用的、和 LLM 解耦的部件。</li></ul><h3 id="dinov2-dinov3-另一条路" tabindex="-1">DINOv2 / DINOv3：另一条路 <a class="header-anchor" href="#dinov2-dinov3-另一条路" aria-label="Permalink to &quot;DINOv2 / DINOv3：另一条路&quot;">​</a></h3><ul><li><strong>是什么</strong>：纯自监督，不用任何文本。它学的是<strong>稠密的空间特征</strong>（哪里是边界、哪些像素属于同一物体），而不是「图文对齐」。</li><li><strong>数字</strong>：DINOv2 用 LVD-142M（1.42 亿图）；<strong>DINOv3 用 LVD-1689M（16.89 亿图，从 170 亿 Instagram 图池里筛出来）</strong>，最大 ViT-7B/16 有 <strong>6,716M 参数</strong>、嵌入维 4096。它在训练约 100 万步后要做一次 <strong>Gram anchoring</strong> 来修复稠密特征坍缩——这是一个诚实的工程细节：<strong>纯自监督在长训练下会自己退化</strong>。</li><li><strong>没有它会坏在哪</strong>：CLIP 系的特征擅长「这是什么」，不擅长「它在哪、有多大、和谁相邻」。分割、深度、对应点这类任务需要 DINO 系的稠密特征。<strong>目前主流 VLM 走的是 CLIP/SigLIP 路线</strong>，这也部分解释了 <a href="#_8-坏在哪里">§8</a> 那些空间推理上的惨败。</li></ul><hr><h2 id="_3-连接器-怎么接进残差流" tabindex="-1">3. 连接器：怎么接进残差流 <a class="header-anchor" href="#_3-连接器-怎么接进残差流" aria-label="Permalink to &quot;3. 连接器：怎么接进残差流&quot;">​</a></h2><blockquote><p>这一节是整篇文章的技术核心。<code>d_vis</code> 和 <code>d_model</code> 不一样宽，中间必须有东西。而这个「东西」怎么设计，是过去三年多模态架构的主要战场。</p></blockquote><h3 id="_1-线性投影-mlp-现在的胜者" tabindex="-1">① 线性投影 / MLP（现在的胜者） <a class="header-anchor" href="#_1-线性投影-mlp-现在的胜者" aria-label="Permalink to &quot;① 线性投影 / MLP（现在的胜者）&quot;">​</a></h3><ul><li><strong>是什么</strong>：一个 1~2 层的 MLP，把 <code>[N, d_vis]</code> 直接投影成 <code>[N, d_model]</code>，然后<strong>当普通 token 拼进序列</strong>。就这么简单。</li><li><strong>数字</strong>：LLaVA-1.5 = CLIP-ViT-L-336px + <strong>两层 MLP</strong>（1.0 版本是单层线性，1.5 升级成 MLP），<strong>576 个视觉 token</strong>，用 120 万条公开数据，<strong>单台 8×A100 训约一天</strong>，在 11 个 benchmark 上 SOTA。</li><li><strong>没有它会坏在哪</strong>：维度对不上，向量根本进不了残差流。</li><li><strong>为什么它赢了</strong>：它保留了<strong>全部</strong> <code>N</code> 个 token 的信息，且不改动 LLM 的任何结构。代价是序列变长——但序列长度问题有 GQA、有 KV 压缩、有<a href="/blog/ai/llm-basics/glossary.html#gqa-mqa-mla-kv-压缩">滑动窗口</a>去解决，而信息丢了就是丢了。<strong>「Don&#39;t be a hero」在这里应验了一次：最简单的方案赢了。</strong></li></ul><h3 id="_2-q-former-perceiver-resampler-被淘汰的路" tabindex="-1">② Q-Former / Perceiver Resampler（被淘汰的路） <a class="header-anchor" href="#_2-q-former-perceiver-resampler-被淘汰的路" aria-label="Permalink to &quot;② Q-Former / Perceiver Resampler（被淘汰的路）&quot;">​</a></h3><ul><li><strong>是什么</strong>：用固定数量的可学习 query 向量，通过交叉注意力从 <code>N</code> 个视觉特征里「抽取」出固定长度的摘要。Flamingo 的 Perceiver Resampler 用 <strong>64 个 latent</strong>，BLIP-2 的 Q-Former 用一组可学习 query。</li><li><strong>数字</strong>：BLIP-2 靠这个设计，<strong>用少 54 倍的可训练参数，在零样本 VQAv2 上比 Flamingo-80B 高 8.7%</strong>。</li><li><strong>没有它会坏在哪</strong>：不压缩的话，高分辨率图的 token 数会失控。</li><li><strong>⚠️ 但它输了</strong>：固定 64 个 latent 意味着<strong>不管图多复杂，信息都被压进同一个瓶颈</strong>。OCR、密集文档、小物体计数——这些恰恰是需要保留细节的场景。轨迹很清楚：<code>Q-Former/Perceiver（2022-23）→ 纯 MLP（LLaVA-1.5，2023）→ MLP + 空间合并（2024-25）</code>。</li></ul><h3 id="_3-交叉注意力适配器-还在用-但代价明确" tabindex="-1">③ 交叉注意力适配器（还在用，但代价明确） <a class="header-anchor" href="#_3-交叉注意力适配器-还在用-但代价明确" aria-label="Permalink to &quot;③ 交叉注意力适配器（还在用，但代价明确）&quot;">​</a></h3><ul><li><strong>是什么</strong>：不把图像 token 拼进序列，而是<strong>在 LLM 内部每隔几层插一个交叉注意力层</strong>，让文本去「查」图像特征。Flamingo 和 Llama 3.2 Vision 走这条路。</li><li><strong>数字</strong>：Llama 3.2 Vision <strong>每 4 层自注意力后插一层交叉注意力</strong>——11B 版本的 GGUF 元数据显示 <code>cross_attention_layers = [3, 8, 13, 18, 23, ...]</code>，40 个 block 里 8 层是交叉注意力。Llama 3 论文明说这些层带来 <strong>约 25% 的参数增量</strong>；如果给 405B 加，光交叉注意力就是 <strong>约 1000 亿参数</strong>（还不算视觉编码器）。标称 11B / 90B 的实际参数是 <strong>10.6B / 88.8B</strong>。</li><li><strong>没有它会坏在哪</strong>：好处很实在——<strong>图像不占文本上下文</strong>，且训练时可以冻结整个语言模型（Llama 3.2 就是这么做的，只更新适配器和视觉编码器）。</li><li><strong>⚠️ 但显存账不划算</strong>：有研究测出交叉注意力层里<strong>图像 token 的 KV Cache 显著超过自注意力层里文本 token 的 KV Cache</strong>，而且砍掉 50% 视觉特征 benchmark 基本不掉。<strong>Llama 4 已经放弃交叉注意力，转向早期融合（<a href="#_7-原生多模态-原生在哪">§7</a>）。</strong></li></ul><h3 id="_4-空间合并-像素重排-真正的降本手段" tabindex="-1">④ 空间合并 / 像素重排（真正的降本手段） <a class="header-anchor" href="#_4-空间合并-像素重排-真正的降本手段" aria-label="Permalink to &quot;④ 空间合并 / 像素重排（真正的降本手段）&quot;">​</a></h3><ul><li><strong>是什么</strong>：在投影之前，把<strong>相邻的 2×2 个 patch 特征拼成一个</strong>，token 数直接砍 4 倍。它压的是空间冗余，不是语义瓶颈——所以比 Q-Former 温和得多。</li><li><strong>数字</strong>： <ul><li>Qwen2-VL：ViT 后接一个 MLP，<strong>把相邻 2×2 token 压成 1 个</strong>。原文的例子：「224×224 的图，patch_size=14，进 LLM 前被压成 <strong>66 个 token</strong>」（256/4 = 64 个 patch token + 2 个视觉起止特殊 token）。ViT 本体 <strong>675M 参数</strong>。</li><li>InternVL 2.5：像素重排把每个 448×448 图块的 <strong>1024 个 token 降到 256 个（4×）</strong>。动态切块最多 12 块 + 1 张缩略图。</li><li>Gemma 3：896×896 进编码器，输出用 <strong>4×4 平均池化</strong>压到 <strong>256 个 token</strong>。</li></ul></li><li><strong>没有它会坏在哪</strong>：不压的话，896×896 / patch 14 = <strong>4096 个 token</strong>——一张图就吃掉 4k 上下文。压到 256 之后才有「一次传 10 张图」的可能。</li><li><strong>这是当前的标准配方</strong>：<code>原生分辨率 ViT → 2×2 合并 → 两层 MLP → 拼进序列</code>。Qwen2.5-VL、InternVL、Gemma 3 用的都是这一套的变体。</li></ul><hr><h2 id="_4-账单-一张图到底多少-token" tabindex="-1">4. 账单：一张图到底多少 token <a class="header-anchor" href="#_4-账单-一张图到底多少-token" aria-label="Permalink to &quot;4. 账单：一张图到底多少 token&quot;">​</a></h2><blockquote><p>这一节是全文最实用的部分。<strong>每一家的公式都不一样，而且都在变。</strong></p></blockquote><h3 id="⚠️-两个必须先纠正的过时说法" tabindex="-1">⚠️ 两个必须先纠正的过时说法 <a class="header-anchor" href="#⚠️-两个必须先纠正的过时说法" aria-label="Permalink to &quot;⚠️ 两个必须先纠正的过时说法&quot;">​</a></h3><ol><li><strong>Claude 的 <code>(宽×高)/750</code> 已经不是官方公式了</strong>。现行文档给的是 <strong>28×28 像素网格</strong>：<code>⌈w/28⌉ × ⌈h/28⌉</code>。（好消息：两者几乎等价——784 px/token vs 750 px/token，说明 <code>/750</code> 一直是同一个网格的近似。作为心算仍然可用，但别当公式写。）</li><li><strong>OpenAI 现在同时跑两套公式</strong>。经典的 <code>85 + 170×tiles</code> 只适用于 GPT-4o / 4.1 / o1 / o3 这一代；新一代模型换成了 <strong>32×32 patch + 1536 上限 + 每模型乘数</strong>。</li></ol><h3 id="openai-a-图块制" tabindex="-1">OpenAI（A）图块制 <a class="header-anchor" href="#openai-a-图块制" aria-label="Permalink to &quot;OpenAI（A）图块制&quot;">​</a></h3><p>先缩到 2048×2048 以内 → 再把短边缩到 768 → 数有多少个 512×512 方块。</p><table tabindex="0"><thead><tr><th>模型</th><th>基数</th><th>每图块</th></tr></thead><tbody><tr><td>GPT-4o / 4.1 / 4.5</td><td>85</td><td>170</td></tr><tr><td><strong>GPT-4o-mini</strong></td><td><strong>2833</strong></td><td><strong>5667</strong></td></tr><tr><td>o1 / o1-pro / o3</td><td>75</td><td>150</td></tr><tr><td>computer-use-preview</td><td>65</td><td>129</td></tr></tbody></table><p><strong>GPT-4o-mini 那一行不是笔误。</strong> 它的图像 token 单价是 4o 的 33 倍——因为它按自己更小的 token 尺度折算。<strong>「用 mini 省钱」这个直觉在图像上直接反过来。</strong></p><h3 id="openai-b-patch-制" tabindex="-1">OpenAI（B）patch 制 <a class="header-anchor" href="#openai-b-patch-制" aria-label="Permalink to &quot;OpenAI（B）patch 制&quot;">​</a></h3><p>适用于 GPT-4.1-mini/nano、o4-mini、GPT-5 系：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>patches = ⌈w/32⌉ × ⌈h/32⌉        上限 1536</span></span>
<span class="line"><span>超限则按 sqrt(32² × 1536 / (w×h)) 缩放后重新数</span></span>
<span class="line"><span>tokens  = patches × 模型乘数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>乘数：GPT-4.1-mini / GPT-5-mini = <strong>1.62</strong>，nano = <strong>2.46</strong>，o4-mini = <strong>1.72</strong>。 官方给的完整例子：1800×2400 → 57×75 = 4275 patch → 缩放到 1056×1408 → <strong>1452 patch</strong>。</p><h3 id="anthropic-claude" tabindex="-1">Anthropic Claude <a class="header-anchor" href="#anthropic-claude" aria-label="Permalink to &quot;Anthropic Claude&quot;">​</a></h3><p><code>⌈w/28⌉ × ⌈h/28⌉</code>，两档上限：</p><table tabindex="0"><thead><tr><th>档位</th><th>模型</th><th>长边上限</th><th>token 上限</th></tr></thead><tbody><tr><td>高分辨率</td><td>Claude 4.7+</td><td><strong>2576 px</strong></td><td><strong>4784</strong></td></tr><tr><td>标准</td><td>其余</td><td><strong>1568 px</strong></td><td><strong>1568</strong></td></tr></tbody></table><p>官方表里最说明问题的一行：<strong>3840×2160 在标准档被缩到 1456×819</strong>——<strong>829 万像素砍到 119 万，丢掉 85%</strong>。高分辨率档保留 2576×1449，token 从 1560 涨到 4784（约 3 倍）。</p><h3 id="google-gemini" tabindex="-1">Google Gemini <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google Gemini&quot;">​</a></h3><ul><li>两边都 ≤ 384 px → <strong>恒定 258 token</strong></li><li>更大 → 切成 <strong>768×768 的块，每块 258 token</strong></li><li>切块单位 = <code>floor(min(w,h) / 1.5)</code></li><li>官方例子：<strong>960×540 → 单位 360 → 3×2 = 6 块</strong></li></ul><h3 id="qwen2-5-vl-开源系的做法" tabindex="-1">Qwen2.5-VL（开源系的做法） <a class="header-anchor" href="#qwen2-5-vl-开源系的做法" aria-label="Permalink to &quot;Qwen2.5-VL（开源系的做法）&quot;">​</a></h3><p><code>tokens = (H/28) × (W/28)</code>，边长向 28 的倍数取整。默认范围 <strong>4 ~ 16,384 token</strong>，推荐区间 <code>min_pixels = 256×28×28</code>（256 token）、<code>max_pixels = 1280×28×28</code>（1280 token）。<strong>它把 token 预算直接暴露成了一个可调参数</strong>——这是开源模型相对闭源 API 最实际的一个优势。</p><h3 id="⭐-同一张-1024×1024-的照片-各家收多少" tabindex="-1">⭐ 同一张 1024×1024 的照片，各家收多少 <a class="header-anchor" href="#⭐-同一张-1024×1024-的照片-各家收多少" aria-label="Permalink to &quot;⭐ 同一张 1024×1024 的照片，各家收多少&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>算法</th><th><strong>token</strong></th></tr></thead><tbody><tr><td>o1 / o3</td><td>75 + 150×4</td><td><strong>675</strong></td></tr><tr><td>GPT-4o / 4.1</td><td>短边→768，2×2=4 块，85+170×4</td><td><strong>765</strong></td></tr><tr><td>Gemini</td><td>单位 682 → 2×2=4 块 × 258</td><td><strong>1,032</strong> ⚠️推导</td></tr><tr><td>Qwen2.5-VL（推荐上限）</td><td>封顶 1280</td><td><strong>1,280</strong></td></tr><tr><td>Claude（两档同值）</td><td>37×37</td><td><strong>1,369</strong></td></tr><tr><td>Qwen2.5-VL（不封顶）</td><td>37×37</td><td><strong>1,369</strong></td></tr><tr><td>GPT-4.1-mini</td><td>1024 patch × 1.62</td><td><strong>~1,659</strong></td></tr><tr><td>o4-mini</td><td>1024 patch × 1.72</td><td><strong>~1,761</strong></td></tr><tr><td>GPT-4.1-nano</td><td>1024 patch × 2.46</td><td><strong>~2,519</strong></td></tr><tr><td><strong>GPT-4o-mini</strong></td><td>2833 + 5667×4</td><td><strong>25,501</strong></td></tr></tbody></table><p>⚠️ Gemini 那一行是我按官方切块规则推导的（用 960×540→6 块的官方例子反推出必须向上取整），不是官方给的例子；GPT-4o 的 765 同理是按文档流程算的。<strong>上生产前用返回里的 <code>usage</code> 字段自己核一遍</strong>——已有开发者报告实际计费高于文档公式。</p><p><strong>读完这张表该记住的</strong>：同一张图，最贵的比最便宜的差 <strong>37 倍</strong>。图像 token 不是一个可以糊弄过去的成本项，它是选型的一个硬输入。</p><hr><h2 id="_5-位置编码-二维的顺序" tabindex="-1">5. 位置编码：二维的顺序 <a class="header-anchor" href="#_5-位置编码-二维的顺序" aria-label="Permalink to &quot;5. 位置编码：二维的顺序&quot;">​</a></h2><h3 id="为什么不能直接用-rope" tabindex="-1">为什么不能直接用 RoPE <a class="header-anchor" href="#为什么不能直接用-rope" aria-label="Permalink to &quot;为什么不能直接用 RoPE&quot;">​</a></h3><p><a href="/blog/ai/llm-basics/glossary.html#位置编码-rope-旋转位置编码">glossary §3</a> 说过：不给位置信息，attention 对输入顺序是<strong>置换等变</strong>的。图像上这个问题更严重——patch 是二维排列的，把它拉平成一维序列，<strong>「上下相邻」这个关系就丢了</strong>。第 1 个 patch 和第 17 个 patch 在图上是垂直相邻，在序列里却隔了 16 位。</p><h3 id="m-rope-qwen2-vl" tabindex="-1">M-RoPE（Qwen2-VL） <a class="header-anchor" href="#m-rope-qwen2-vl" aria-label="Permalink to &quot;M-RoPE（Qwen2-VL）&quot;">​</a></h3><ul><li><strong>是什么</strong>：把 RoPE 的旋转维度<strong>拆成三组：时间 / 高 / 宽</strong>。文本 token 三个 ID 相同（退化成普通 RoPE），图像 token 时间维恒定、高宽维变化，视频 token 三维全动。</li><li><strong>数字</strong>：通道切分从发布的 config 里能直接读到——<code>mrope_section = [16, 24, 24]</code>，即 16 维给时间、24 维给高、24 维给宽。（注意：这是 config 里的值，论文正文没写死这个切分。）</li><li><strong>没有它会坏在哪</strong>：模型无法判断两个 patch 是「左右相邻」还是「上下相邻」，所有空间关系推理（「杯子在书的左边」）都无从谈起。</li></ul><h3 id="其他做法" tabindex="-1">其他做法 <a class="header-anchor" href="#其他做法" aria-label="Permalink to &quot;其他做法&quot;">​</a></h3><ul><li><strong>RoPE-2D</strong>（Pixtral）：直接把旋转按二维展开，支持任意分辨率和长宽比，<strong>最大 1024×1024</strong>，并加了 <code>[IMG BREAK]</code> / <code>[IMG END]</code> 特殊 token 来标记换行和结束——<strong>行边界得显式告诉模型，因为拉平之后它看不出来</strong>。</li><li><strong>轴向 RoPE</strong>（DINOv3）：配合 box jittering 数据增强，训练时只用 256 分辨率，<strong>推理能稳到 4k</strong>。</li><li><strong>插值</strong>（最经典的一招）：CLIP 的 336px 模型不是重训的，它的位置编码是<strong>从 224px 模型插值出来的</strong>，再多训一个 epoch。这是变分辨率的标准做法。</li><li><strong>Qwen2.5-VL 的绝对时间编码</strong>：让时间维 ID 对齐真实墙上时钟，这才有了「秒级事件定位」。</li></ul><hr><h2 id="_6-视频与音频-把时间也切成-token" tabindex="-1">6. 视频与音频：把时间也切成 token <a class="header-anchor" href="#_6-视频与音频-把时间也切成-token" aria-label="Permalink to &quot;6. 视频与音频：把时间也切成 token&quot;">​</a></h2><h3 id="视频" tabindex="-1">视频 <a class="header-anchor" href="#视频" aria-label="Permalink to &quot;视频&quot;">​</a></h3><p>视频没有新机制，就是<strong>图像 × 帧数</strong>。全部的设计空间只有两个旋钮：<strong>采样率</strong>和<strong>每帧 token 数</strong>。</p><p><strong>Gemini 的账（官方数字，最清楚）</strong>：</p><ul><li>采样 <strong>1 fps</strong></li><li>默认 <strong>258 token/帧</strong>；低分辨率档 <strong>66 token/帧</strong></li><li>音轨 <strong>32 token/秒</strong></li><li>合计：默认 <strong>约 300 token/秒</strong>，低分辨率 <strong>约 100 token/秒</strong></li><li><strong>⭐ 一分钟视频 ≈ 18,000 token（默认）/ 6,000 token（低分辨率）</strong></li><li>100 万上下文能装 <strong>1 小时</strong>（默认）或 <strong>3 小时</strong>（低分辨率）</li></ul><p><strong>Qwen2-VL</strong>：采样 <strong>2 fps</strong>，但<strong>每个视频总 token 硬性封顶 16,384</strong>——采样率和总预算是两个独立的闸门。</p><p><strong>没有它会坏在哪</strong>：不封顶的话，一分钟 1080p 视频按每帧 1560 token（Claude 标准档）× 30 fps = <strong>281 万 token</strong>，任何模型都装不下。<strong>所有视频多模态本质上都是在做激进的时间降采样</strong>——1 fps 意味着你丢掉了 96.7% 的帧。快速动作、瞬时事件，模型在物理上就看不见。</p><h3 id="音频" tabindex="-1">音频 <a class="header-anchor" href="#音频" aria-label="Permalink to &quot;音频&quot;">​</a></h3><ul><li><strong>Whisper 编码器</strong>（几乎所有音频前端的祖宗）：<strong>68 万小时</strong>训练，<strong>30 秒</strong>定长窗口，80 通道 log-Mel，25ms 窗 / 10ms 跳，一个 30 秒窗产出 <strong>1500 帧</strong>（即 50 帧/秒）。</li><li><strong>GPT-4o Realtime</strong> 的计费口径最直白：<strong>用户音频 1 token / 100ms（10 token/秒 ≈ 600/分钟）</strong>，<strong>助手音频 1 token / 50ms（20 token/秒 ≈ 1200/分钟）</strong>。静音不产生 token。</li><li><strong>Qwen2-Audio</strong>：编码器从 Whisper-large-v3 初始化，加一个 stride=2 的池化层，<strong>每帧约对应 40ms，即 25 Hz / 25 token 每秒</strong>。</li><li><strong>Mimi / Moshi</strong>（离散音频编解码）：24kHz 音频 → <strong>12.5 Hz 帧率</strong>，<strong>8 个码本</strong> → <strong>100 token/秒</strong>，码率 <strong>1.1 kbps</strong>，端到端延迟 80ms。设计动机写得很直白：<strong>12.5 Hz 是在向文本 token 约 3-4 Hz 的速率靠拢</strong>——让音频和文本在同一个数量级上，才能塞进同一个自回归循环。</li><li><strong>SNAC</strong>：多尺度 RVQ，三层量化器跑在<strong>不同时间分辨率</strong>（12 / 23 / 47 Hz）上，合计 <strong>约 82 token/秒</strong>，0.98 kbps，19.8M 参数。</li></ul><p><strong>没有它会坏在哪</strong>：音频天然是每秒 16,000 个采样点。不做 100~1000 倍的降采样，它连一句话都进不了上下文。<strong>「实时语音对话」这件事的全部工程难点，就是把这个降采样做到既省 token 又不丢语义。</strong></p><hr><h2 id="_7-原生多模态-原生在哪" tabindex="-1">7. 原生多模态：原生在哪 <a class="header-anchor" href="#_7-原生多模态-原生在哪" aria-label="Permalink to &quot;7. 原生多模态：原生在哪&quot;">​</a></h2><p>「原生多模态」这个词被用滥了。它只有一个技术含义：<strong>图像编码器是不是和 LLM 一起从头训的，而不是事后接上去的。</strong></p><h3 id="后期融合-接上去的" tabindex="-1">后期融合（接上去的） <a class="header-anchor" href="#后期融合-接上去的" aria-label="Permalink to &quot;后期融合（接上去的）&quot;">​</a></h3><p>预训练好的 ViT + 预训练好的 LLM，中间训一个连接器。LLaVA、Llama 3.2 Vision、Gemma 3 都是这类（Gemma 3 甚至<strong>全程冻结</strong>视觉编码器）。优点是便宜、模块可复用；缺点是编码器的语义边界在多模态训练开始前就定死了。</p><h3 id="早期融合-一起训的" tabindex="-1">早期融合（一起训的） <a class="header-anchor" href="#早期融合-一起训的" aria-label="Permalink to &quot;早期融合（一起训的）&quot;">​</a></h3><p>图像被转成<strong>离散 token</strong>，和文本 token <strong>共享同一张词表</strong>，从预训练第一步就混在一起。</p><ul><li><strong>Chameleon（Meta）</strong>：512×512 图 → <strong>1024 个离散 token</strong>，码本大小 <strong>8192</strong>；BPE 词表 <strong>65,536，其中 8192 个就是图像码本</strong>——文本和图像在字面意义上共用一个词表。训练 <strong>9.2T token</strong>、2.1 个 epoch，7B / 34B 两档，用 <strong>QK-Norm</strong> 稳训练。</li><li><strong>Emu3</strong>：纯 next-token 预测，<strong>8B 参数</strong>，视觉 tokenizer 做 8×8 空间压缩、码本 <strong>32,768</strong>、4× 时间压缩。理解和生成都不用扩散、不用组合系统。</li><li><strong>Llama 4</strong>：官方措辞是「<strong>early fusion</strong>，把文本和视觉 token 统一进同一个主干」，视觉编码器基于 MetaCLIP 但<strong>配合一个冻结的 Llama 重新训过</strong>。Scout 是 17B 激活 / 16 专家 / 109B 总参 / 10M 上下文；Maverick 是 17B 激活 / 128 专家 / 400B 总参。官方只承诺<strong>最多 8 张图</strong>的后训练效果。</li></ul><h3 id="哪条路对" tabindex="-1">哪条路对 <a class="header-anchor" href="#哪条路对" aria-label="Permalink to &quot;哪条路对&quot;">​</a></h3><p>Apple 那篇《Scaling Laws for Native Multimodal Models》（ICCV 2025 oral）训了 <strong>457 个模型</strong>来回答这个问题，结论很直接：</p><blockquote><p><strong>后期融合相对早期融合没有内在优势。</strong> 早期融合在小参数量下表现更强、训练更省、部署更简单。</p></blockquote><p>而且它指出 <strong>MoE 让模型能自己学出模态专属的权重</strong>，这对早期融合是实质性加成——<a href="/blog/ai/llm-basics/glossary.html#moe-mixture-of-experts-激活参数">glossary §4</a> 说 MoE 只作用在 FFN 上，那么在多模态里，<strong>不同专家自然会分化去处理不同模态</strong>。这也解释了 Llama 4 为什么同时选了早期融合和 MoE。</p><p>⚠️ <strong>GPT-4o 和 Gemini 的「原生」是厂商说法，没有公开架构细节</strong>——没有参数量、没有 tokenizer 规格、没有融合方式。别把它们当技术论据用。</p><hr><h2 id="_8-坏在哪里" tabindex="-1">8. 坏在哪里 <a class="header-anchor" href="#_8-坏在哪里" aria-label="Permalink to &quot;8. 坏在哪里&quot;">​</a></h2><p>多模态最反直觉的一点：<strong>这些模型的「看」和人类的「看」，重合度远低于 demo 给人的印象。</strong></p><h3 id="blink-最强的一记耳光" tabindex="-1">BLINK：最强的一记耳光 <a class="header-anchor" href="#blink-最强的一记耳光" aria-label="Permalink to &quot;BLINK：最强的一记耳光&quot;">​</a></h3><p>3,807 道选择题，考的全是经典 CV 任务（相对深度、视觉对应、多视角推理、伪造检测）——<strong>人类平均 95.70%</strong>，而：</p><blockquote><p><strong>GPT-4V 51.26%，Gemini 45.72%——只比随机猜（38.09%）高 13.17 和 7.63 个百分点。</strong></p></blockquote><p>论文的措辞很克制也很致命：这些感知能力在多模态 LLM 上「<strong>尚未涌现</strong>」，因为这类任务「<strong>抵抗通过自然语言中介</strong>」。</p><p>翻译一下：<strong>能被语言描述的视觉任务，模型做得不错；不能被语言描述的，它基本在瞎猜。</strong> 这直接对应 <a href="#_2-视觉编码器-把-patch-变成向量">§2</a> 那个判断——主流 VLM 用的是 CLIP/SigLIP 的图文对齐特征，不是 DINO 系的稠密空间特征。<strong>它学的一直是「怎么用语言描述这张图」，不是「这张图的几何结构是什么」。</strong></p><h3 id="其他有数字的失败面" tabindex="-1">其他有数字的失败面 <a class="header-anchor" href="#其他有数字的失败面" aria-label="Permalink to &quot;其他有数字的失败面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>benchmark</th><th>最好成绩</th><th>参照</th></tr></thead><tbody><tr><td><strong>BLINK</strong></td><td>GPT-4V <strong>51.26%</strong></td><td>人类 95.70%，随机 38.09%</td></tr><tr><td><strong>MathVista</strong></td><td>GPT-4V <strong>49.9%</strong></td><td>人类 60.3%（差 10.4 分）</td></tr><tr><td><strong>MMMU</strong></td><td>Gemini Ultra <strong>59%</strong> / GPT-4V 56%</td><td>11.5K 题，30 学科</td></tr></tbody></table><p>MathVista 论文对失败原因的判断是「难以理解复杂图形、难以做严格推理」。InternVL 2.5 报告 CoT 能给 MMMU <strong>+3.7 分</strong>——说明有一部分失败是<strong>推理侧</strong>的，不全是感知侧。这两类失败要分开看，修法完全不同。</p><h3 id="分辨率悬崖-可量化" tabindex="-1">分辨率悬崖（可量化） <a class="header-anchor" href="#分辨率悬崖-可量化" aria-label="Permalink to &quot;分辨率悬崖（可量化）&quot;">​</a></h3><p>Claude 的两档上限是公开数据里最干净的例子：同一张 3840×2160 的图，标准档缩到 1456×819（<strong>丢 85% 像素</strong>，1560 token），高分辨率档保留 2576×1449（4784 token，<strong>约 3 倍</strong>）。<strong>小字 OCR 就是在这条线上失败的</strong>——不是模型「不认识字」，是那些字在进编码器之前已经被插值抹掉了。</p><p>Anthropic 自己列的限制里还有几条值得抄下来：<strong>200 像素以下的小图</strong>、旋转图、多次 JPEG 压缩的图会诱发幻觉；坐标定位是近似值；<strong>「大量小物体的计数不保证准确」</strong>。</p><p>计数这一条特别能说明问题。数数在人看来是最简单的视觉任务，但对模型来说——它没有一个「逐个指认并累加」的机制，只有一次前向里的加权平均。<strong><a href="/blog/ai/llm-basics/glossary.html#注意力-attention-qkv">glossary §3</a> 说 attention 是加权求和，加权求和天生不会数数。</strong></p><hr><h2 id="_9-一句话收尾" tabindex="-1">9. 一句话收尾 <a class="header-anchor" href="#_9-一句话收尾" aria-label="Permalink to &quot;9. 一句话收尾&quot;">​</a></h2><p>图像变成 token 之后，模型不知道自己在看图。这是多模态能这么快铺开的原因——<strong>不用改架构，只用改入口</strong>。</p><p>也是它现在这些毛病的原因。整条链路的每一环都在把二维的、连续的、高信息量的东西，压成一维的、离散的、几百个 token 的序列，然后指望一个从文本里学会推理的模型在这上面做几何。它在能被语言描述的部分做得很好，在其余部分接近随机。</p><p><strong><code>N</code> 是唯一的自变量。</strong> 成本、分辨率、能不能读小字、能不能数清楚——全在这一个数上。</p><hr><h2 id="附-本文用到的未定论-未公开项" tabindex="-1">附：本文用到的未定论/未公开项 <a class="header-anchor" href="#附-本文用到的未定论-未公开项" aria-label="Permalink to &quot;附：本文用到的未定论/未公开项&quot;">​</a></h2><p>写技术文档最容易出问题的地方是把「厂商说法」当「已验证事实」。下面这些我在正文里做了标注，这里再集中列一次：</p><ul><li><strong>GPT-4o / Gemini 的内部架构</strong>：未公开，「原生多模态」是厂商措辞，无法作为技术论据。</li><li><strong>Llama 4 的单图 token 数</strong>：官方未发布。</li><li><strong>Gemini 1024×1024 = 1032 token</strong>、<strong>GPT-4o = 765 token</strong>：按官方规则推导，非官方给出的例子，生产前请用 <code>usage</code> 字段核对。</li><li><strong>Q-Former 的 query 数与参数量</strong>：常见的「32 个 query / 188M」我没能从论文正文确认，正文中未采用。</li><li><strong>Claude 的 <code>(w×h)/750</code></strong>：已被 28px 网格公式取代，仅可作心算近似。</li></ul>`,116)])])}const m=o(a,[["render",e]]);export{h as __pageData,m as default};
